from pathlib import Path
import csv,json,html
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'outputs'
def main():
    m=json.loads((OUT/'metrics.json').read_text());plt.rcParams.update({'svg.hashsalt':'utility-reliability-v2','font.family':'DejaVu Sans','axes.spines.top':False,'axes.spines.right':False})
    fig,axes=plt.subplots(1,2,figsize=(11,4.2),layout='constrained')
    axes[0].bar(['Last report',m['selected_model']],[m['baseline_test']['lag_customer_weighted_mae'],m['selected_test']['lag_customer_weighted_mae']],color=['#6b8295','#008589']);axes[0].set_ylabel('Lag-customer-weighted MAE (minutes)');axes[0].set_title('2025 report-year diagnostic')
    b=m['bootstrap'];x=b['mean_weighted_error_reduction'];lo,hi=b['percentile_95'];axes[1].errorbar([x],[0],xerr=[[x-lo],[hi-x]],fmt='o',capsize=7,color='#008589');axes[1].axvline(0,color='#a04425',linestyle='--');axes[1].set_yticks([]);axes[1].set_xlabel('Absolute-error reduction vs last report (minutes)');axes[1].set_title('95% utility-cluster bootstrap interval\nCrosses zero: improvement is inconclusive')
    fig.savefig(OUT/'predictive_evidence.svg',metadata={'Date':None});fig.savefig(OUT/'predictive_evidence.png',dpi=160,metadata={'Software':'Utility Reliability Lab'});plt.close(fig)
    with (OUT/'published_state_reconciliation.csv').open() as f:recon=list(csv.DictReader(f))
    fig,ax=plt.subplots(figsize=(10,4.3),layout='constrained')
    for year in sorted({r['year'] for r in recon}):
        g=[r for r in recon if r['year']==year];ax.scatter([int(year)]*len(g),[float(r['difference']) for r in g],alpha=.55,label=year,s=24)
    ax.axhline(.11,color='#a04425',linestyle='--',linewidth=1);ax.axhline(-.11,color='#a04425',linestyle='--',linewidth=1);ax.set_xticks(sorted({int(r['year']) for r in recon}));ax.set_xlabel('Source report year');ax.set_ylabel('Recomputed minus published SAIDI (minutes)');ax.set_title('State-summary reconciliation exposes a release-quality exception');fig.savefig(OUT/'release_reconciliation.svg',metadata={'Date':None});plt.close(fig)
    sections=[
      ('Decision status',f"Use the {m['decision_view_year']} reconciled release for descriptive due diligence. Quarantine {m['quarantined_years']} from decision inputs: {m['state_reconciliation_exceptions']} state summaries fail the configured 0.11-minute comparison. This is an unexplained discrepancy between source components, not evidence that utilities misreported or that EIA data are generally unreliable. No predictive component is promoted."),
      ('What is actually observed',f"Six official EIA reliability workbooks, 2020–2025, normalize to {m['panel_rows']:,} method-specific records covering {m['utility_state_keys']:,} utility-state keys. IEEE and Other standards are separate. {m['latest_valid_ieee']} positive-customer, normal-day IEEE observations appear in the audited {m['decision_view_year']} view. Every row retains workbook, sheet and row number. A blank method block is not interpreted as a zero outage or as proof of nonresponse."),
      ('Peer review design','Peer cohorts exclude every row from the same utility, including its other states. Cohorts use state/ownership when at least 15 other observations exist, otherwise ownership/size, ownership, then national fallback. These are descriptive size/ownership comparisons; terrain, hazard, density and asset condition are not controlled. A high percentile is a review signal, not evidence of poor management.'),
      ('Predictive evaluation',f"2023 chooses among last report, three-report median and three peer-shrinkage weights; 2024 calibrates intervals; 2025 is held out for diagnostics. Selected model: {m['selected_model']}. Weighted MAE {m['selected_test']['lag_customer_weighted_mae']:.2f} vs baseline {m['baseline_test']['lag_customer_weighted_mae']:.2f} minutes, using lagged customer weights. Utility-cluster bootstrap improvement interval [{lo:.2f}, {hi:.2f}] crosses zero; nominal 90% band coverage is {m['empirical_90_interval_coverage']:.1%}. The predictive gate therefore fails. Balanced six-year cohort results are reported separately to expose attrition sensitivity."),
      ('Timing and vintage limitation','Splits respect report years, not historical release timestamps. All files are final snapshots downloaded in October 2026; original historical release vintages were not reconstructed. Accordingly this is a next-report benchmark diagnostic, not proof of a deployable January-1 annual forecast or real-time nowcast. 2025 diagnostics remain exploratory because that release is quarantined from the decision view.'),
      ('Investment screen','The workbench computes a break-even up-front social cost from observed customer exposure and user-entered reduction, customer-hour valuation, O&M, rate and life assumptions. No intervention effectiveness is estimated. The value is not utility profit, lost revenue, regulatory cost recovery or an engineering design. A positive conditional surplus only defines assumptions worth investigating; it does not justify an investment.'),
      ('What to investigate next','First reconcile the 26 state-level source-component differences and determine whether revisions, scope or an extraction issue explain them. Then obtain engineering cost/effectiveness evidence and relevant weather, density and asset-condition covariates. Re-test predictive coverage and uncertainty with multiple independently held-out years and publication-date vintages. No source-provider contact or communication has been sent.'),
      ('Personal understanding','I can distinguish a functioning model from a justified decision. Here the apparent forecasting improvement is uncertain, and a newer source release fails a consistency check. The defensible action is to retain the reconciled release, expose the issues and withhold predictive promotion. That judgment is more useful than adding complexity and presenting a confident but unsupported investment recommendation.'),
      ('Sources','U.S. Energy Information Administration, Form EIA-861 detailed data: https://www.eia.gov/electricity/data/eia861/ . Official ZIP URLs, hashes, original reliability workbooks and exact row lineage are bundled. Government-source values are observed; scenario assumptions and modeled outputs are labeled separately.')]
    memo='# Utility Reliability Due Diligence Lab\n\nREAL UTILITY PANEL · RELEASE QUALITY GATES · CONDITIONAL ECONOMICS\n\n'+''.join('## '+h+'\n\n'+b+'\n\n' for h,b in sections)
    (OUT/'executive_memo.md').write_text(memo)
    page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Utility Reliability | Evidence Review</title><style>body{background:#eef3f6;color:#173146;font:17px/1.65 system-ui;margin:0}main{max-width:1120px;margin:auto;padding:30px 22px}section,header,figure{background:white;border-radius:12px;padding:26px;margin:20px 0;border:1px solid #d9e3eb}header{border-top:7px solid #008589}h1{line-height:1.15;font-size:37px}h2{color:#007f82}img{width:100%}p{white-space:pre-wrap}a{color:#007f82}</style><main><header><small>UTILITY RELIABILITY · ANALYST EVIDENCE REVIEW</small><h1>Separate observed risk, model uncertainty and investment assumptions.</h1><p><a href="workbench.html">Open the offline interactive workbench</a></p></header><figure><img src="predictive_evidence.svg" alt="Held-out model error and inconclusive cluster-bootstrap interval"></figure><figure><img src="release_reconciliation.svg" alt="State reconciliation differences across report years"></figure>'+''.join('<section><h2>'+html.escape(h)+'</h2><p>'+html.escape(b)+'</p></section>' for h,b in sections)+'</main></html>'
    (OUT/'report.html').write_text(page)
if __name__=='__main__':main()
